functions.code:
def negate_if_odd(x: int) -> int:
    if x % 2:
        return -x
    return x

def add_seven_if_negative(x: int) -> int:
    if x < 0:
        return x + 7
    return x

def distance_to_nearest_multiple_of_five(x: int) -> int:
    r = x % 5
    return min(r, 5 - r)

def triangular_number_of_absolute(x: int) -> int:
    n = abs(x)
    return n * (n + 1) // 2

def factorial_of_small_digit(x: int) -> int:
    n = abs(x) % 10
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def product_of_nonzero_digits(x: int) -> int:
    result = 1
    for ch in str(abs(x)):
        d = int(ch)
        if d != 0:
            result *= d
    return result

def digital_root_value(x: int) -> int:
    n = abs(x)
    if n == 0:
        return 0
    return 1 + (n - 1) % 9

def palindrome_indicator(x: int) -> int:
    s = str(abs(x))
    return 1 if s == s[::-1] else 0

def next_multiple_of_four(x: int) -> int:
    r = x % 4
    return x if r == 0 else x + (4 - r)

def clamp_to_ten(x: int) -> int:
    if x < -10:
        return -10
    if x > 10:
        return 10
    return x

def sign_times_square(x: int) -> int:
    if x < 0:
        return -(x * x)
    return x * x

def difference_between_digit_sum_and_length(x: int) -> int:
    s = str(abs(x))
    return sum(int(ch) for ch in s) - len(s)

def sum_of_first_n_odds_abs(x: int) -> int:
    n = abs(x)
    return n * n

def square_of_digit_sum(x: int) -> int:
    s = sum(int(ch) for ch in str(abs(x)))
    return s * s

def odd_even_balance(x: int) -> int:
    odds = 0
    evens = 0
    for ch in str(abs(x)):
        if int(ch) % 2:
            odds += 1
        else:
            evens += 1
    return odds - evens

def last_digit_times_first_digit(x: int) -> int:
    s = str(abs(x))
    return int(s[0]) * int(s[-1])

def unsigned_mirror_gap(x: int) -> int:
    n = abs(x)
    r = int(str(n)[::-1])
    return abs(n - r)

def sum_of_squares_to_abs(x: int) -> int:
    n = abs(x)
    return n * (n + 1) * (2 * n + 1) // 6

def remainder_plus_quotient_by_five(x: int) -> int:
    q, r = divmod(x, 5)
    return q + r

def nearest_power_of_two_exponent_floor(x: int) -> int:
    n = abs(x)
    if n == 0:
        return -1
    return n.bit_length() - 1

def two_to_bit_length_minus_one(x: int) -> int:
    b = abs(x).bit_length()
    return (1 << b) - 1

def increment_until_even_count_digits(x: int) -> int:
    if len(str(abs(x))) % 2 == 1:
        return x + 1
    return x

def decrement_if_divisible_by_four(x: int) -> int:
    if x % 4 == 0:
        return x - 1
    return x

def sum_of_even_digits(x: int) -> int:
    total = 0
    for ch in str(abs(x)):
        d = int(ch)
        if d % 2 == 0:
            total += d
    return total

def sum_of_odd_digits(x: int) -> int:
    total = 0
    for ch in str(abs(x)):
        d = int(ch)
        if d % 2 == 1:
            total += d
    return total

def first_digit_minus_last_digit(x: int) -> int:
    s = str(abs(x))
    return int(s[0]) - int(s[-1])

def last_digit_minus_first_digit(x: int) -> int:
    s = str(abs(x))
    return int(s[-1]) - int(s[0])

def count_digits_times_last_digit(x: int) -> int:
    s = str(abs(x))
    return len(s) * int(s[-1])

def count_digits_plus_first_digit(x: int) -> int:
    s = str(abs(x))
    return len(s) + int(s[0])

def duplicate_last_digit_value(x: int) -> int:
    d = abs(x) % 10
    return d * 10 + d

def leading_trailing_digit_sum(x: int) -> int:
    s = str(abs(x))
    return int(s[0]) + int(s[-1])

def leading_trailing_digit_product(x: int) -> int:
    s = str(abs(x))
    return int(s[0]) * int(s[-1])

def trailing_zero_count(x: int) -> int:
    s = str(abs(x))
    return len(s) - len(s.rstrip('0'))

def remove_first_digit(x: int) -> int:
    s = str(abs(x))
    return int(s[1:]) if len(s) > 1 else 0

def swap_first_last_digits(x: int) -> int:
    s = str(abs(x))
    if len(s) == 1:
        return int(s)
    return int(s[-1] + s[1:-1] + s[0])

def repeat_first_digit_twice(x: int) -> int:
    d = str(abs(x))[0]
    return int(d + d)

def repeat_last_digit_thrice(x: int) -> int:
    d = str(abs(x))[-1]
    return int(d + d + d)

def sign_code(x: int) -> int:
    if x < 0:
        return -1
    if x > 0:
        return 1
    return 0

def sum_range_zero_to_abs(x: int) -> int:
    n = abs(x)
    return n * (n + 1) // 2

def odd_square_even_cube(x: int) -> int:
    if x % 2:
        return x * x
    return x * x * x

def even_square_odd_cube(x: int) -> int:
    if x % 2 == 0:
        return x * x
    return x * x * x

def multiple_of_five_bonus(x: int) -> int:
    if x % 5 == 0:
        return x + 5
    return x

def multiple_of_six_penalty(x: int) -> int:
    if x % 6 == 0:
        return x - 6
    return x

def count_divisors_of_absolute(x: int) -> int:
    n = abs(x)
    if n == 0:
        return 0
    count = 0
    for i in range(1, n + 1):
        if n % i == 0:
            count += 1
    return count

def is_prime_indicator_abs(x: int) -> int:
    n = abs(x)
    if n < 2:
        return 0
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return 0
    return 1

def largest_proper_divisor_abs(x: int) -> int:
    n = abs(x)
    if n <= 1:
        return 0
    for i in range(n // 2, 0, -1):
        if n % i == 0:
            return i
    return 0

def smallest_divisor_ge_two_abs(x: int) -> int:
    n = abs(x)
    if n < 2:
        return 0
    for i in range(2, n + 1):
        if n % i == 0:
            return i
    return 0

def gcd_with_twelve(x: int) -> int:
    a = abs(x)
    b = 12
    while b:
        a, b = b, a % b
    return a

def lcm_with_six(x: int) -> int:
    a = abs(x)
    if a == 0:
        return 0
    b = 6
    g1, g2 = a, b
    while g2:
        g1, g2 = g2, g1 % g2
    return a * b // g1

def fibonacci_index_small(x: int) -> int:
    n = abs(x) % 20
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def sum_of_factorials_of_digits(x: int) -> int:
    total = 0
    for ch in str(abs(x)):
        d = int(ch)
        f = 1
        for i in range(2, d + 1):
            f *= i
        total += f
    return total

def descending_digit_sort_value(x: int) -> int:
    s = ''.join(sorted(str(abs(x)), reverse=True))
    return int(s)

def ascending_digit_sort_value(x: int) -> int:
    s = ''.join(sorted(str(abs(x))))
    return int(s)
